const pptxgen = require('pptxgenjs');

let pptx = new pptxgen();

// Layout and formatting
pptx.layout = 'LAYOUT_16x9';

// Colors (Midnight Executive inspired)
const COLOR_BG = '0B132B';
const COLOR_CARD = '1C2541';
const COLOR_TEXT_PRIMARY = 'FFFFFF';
const COLOR_TEXT_SECONDARY = '8D99AE';
const COLOR_ACCENT = '5BC0BE';
const COLOR_ACCENT2 = '3A506B';

// Default text styles
pptx.defineSlideMaster({
  title: 'MASTER_SLIDE',
  background: { color: COLOR_BG },
  slideNumber: { x: 12.8, y: 7.0, w: 0.5, h: 0.3, color: COLOR_TEXT_SECONDARY, fontSize: 10, align: 'right' }
});

// Helper for title
function addHeader(slide, text) {
  slide.addText(text, {
    x: 0.5,
    y: 0.4,
    w: 12.3,
    h: 0.8,
    fontSize: 28,
    bold: true,
    color: COLOR_ACCENT,
    fontFace: 'Trebuchet MS'
  });

  // Underline accent
  slide.addShape(pptx.ShapeType.rect, {
    x: 0.5,
    y: 1.25,
    w: 12.3,
    h: 0.02,
    fill: { color: COLOR_ACCENT2 }
  });
}

// Slide 1: Title Slide
let slide1 = pptx.addSlide({ masterName: 'MASTER_SLIDE' });
slide1.addShape(pptx.ShapeType.rect, { x: 0, y: 0, w: 1.0, h: 7.5, fill: { color: COLOR_ACCENT } });
slide1.addText('VAPO: Value-Model-Based RL for Advanced Reasoning', {
  x: 1.5, y: 2.2, w: 11, h: 1.2,
  fontSize: 44, bold: true, color: COLOR_TEXT_PRIMARY, fontFace: 'Trebuchet MS'
});
slide1.addText('60.4 on AIME 2024', {
  x: 1.5, y: 3.5, w: 11, h: 0.8,
  fontSize: 32, color: COLOR_ACCENT, fontFace: 'Trebuchet MS', bold: true
});
slide1.addText('Authors: ByteDance Seed\nBase Model: Qwen2.5-32B\nSFT Data: None', {
  x: 1.5, y: 5.0, w: 11, h: 1.2,
  fontSize: 18, color: COLOR_TEXT_SECONDARY, fontFace: 'Calibri', lineSpacing: 24
});

// Slide 2: Why Value Models?
let slide2 = pptx.addSlide({ masterName: 'MASTER_SLIDE' });
addHeader(slide2, 'Why Value Models? Finer Credit Assignment for Long CoT');

// Two columns comparing
slide2.addShape(pptx.ShapeType.rect, { x: 0.5, y: 1.8, w: 5.8, h: 4.8, fill: { color: COLOR_CARD }, rectRadius: 0.1 });
slide2.addText('Value-Model-Free (GRPO, DAPO)', { x: 0.8, y: 2.1, w: 5.2, h: 0.5, fontSize: 22, bold: true, color: COLOR_TEXT_PRIMARY });
slide2.addText(
  [
    { text: 'Uniform Advantage:', options: { bold: true, color: 'FF6B6B' } },
    { text: ' Computes advantage based on final trajectory reward and assigns it uniformly across all tokens.', options: { breakLine: true } },
    { text: 'Limitation:', options: { bold: true, color: 'FF6B6B' } },
    { text: ' Struggles with precise credit assignment when subtle step-level errors cause catastrophic failures.' }
  ],
  { x: 0.8, y: 2.8, w: 5.2, h: 3.5, fontSize: 16, color: COLOR_TEXT_SECONDARY, valign: 'top', bullet: { type: 'bullet' } }
);

slide2.addShape(pptx.ShapeType.rect, { x: 7.0, y: 1.8, w: 5.8, h: 4.8, fill: { color: COLOR_CARD }, rectRadius: 0.1 });
slide2.addText('Value-Model-Based (VAPO)', { x: 7.3, y: 2.1, w: 5.2, h: 0.5, fontSize: 22, bold: true, color: COLOR_ACCENT });
slide2.addText(
  [
    { text: 'Token-Level Credit:', options: { bold: true, color: COLOR_ACCENT } },
    { text: ' Enables precise tracking of each action\'s impact on returns.', options: { breakLine: true } },
    { text: 'Variance Reduction:', options: { bold: true, color: COLOR_ACCENT } },
    { text: ' Provides lower-variance estimates per token compared to Monte Carlo methods.', options: { breakLine: true } },
    { text: 'Generalization:', options: { bold: true, color: COLOR_ACCENT } },
    { text: ' Well-trained value models generalize across samples, improving efficiency.' }
  ],
  { x: 7.3, y: 2.8, w: 5.2, h: 3.5, fontSize: 16, color: COLOR_TEXT_PRIMARY, valign: 'top', bullet: { type: 'bullet' } }
);

// Slide 3: Three Core Challenges
let slide3 = pptx.addSlide({ masterName: 'MASTER_SLIDE' });
addHeader(slide3, 'Three Challenges Plaguing Value-Model-Based RL in Long-CoT Tasks');

const cardY = 2.0;
const cardH = 4.0;
const cardW = 3.8;

// Card 1
slide3.addShape(pptx.ShapeType.rect, { x: 0.5, y: cardY, w: cardW, h: cardH, fill: { color: COLOR_CARD }, rectRadius: 0.1 });
slide3.addText('1', { x: 0.5, y: cardY + 0.3, w: cardW, h: 0.6, fontSize: 36, bold: true, color: COLOR_ACCENT, align: 'center' });
slide3.addText('Value Model Bias', { x: 0.8, y: cardY + 1.2, w: cardW - 0.6, h: 0.5, fontSize: 20, bold: true, color: COLOR_TEXT_PRIMARY, align: 'center' });
slide3.addText('Bootstrapped learning over long trajectories compounds errors, leading to significant initial bias in value estimation.', { x: 0.8, y: cardY + 1.8, w: cardW - 0.6, h: 2.0, fontSize: 15, color: COLOR_TEXT_SECONDARY, align: 'center', valign: 'top' });

// Card 2
slide3.addShape(pptx.ShapeType.rect, { x: 4.75, y: cardY, w: cardW, h: cardH, fill: { color: COLOR_CARD }, rectRadius: 0.1 });
slide3.addText('2', { x: 4.75, y: cardY + 0.3, w: cardW, h: 0.6, fontSize: 36, bold: true, color: COLOR_ACCENT, align: 'center' });
slide3.addText('Heterogeneous Sequence Lengths', { x: 5.05, y: cardY + 1.2, w: cardW - 0.6, h: 0.5, fontSize: 20, bold: true, color: COLOR_TEXT_PRIMARY, align: 'center' });
slide3.addText('Variable response lengths require different bias-variance tradeoffs. Uniform GAE parameters fail to optimize across both short and long responses.', { x: 5.05, y: cardY + 1.8, w: cardW - 0.6, h: 2.0, fontSize: 15, color: COLOR_TEXT_SECONDARY, align: 'center', valign: 'top' });

// Card 3
slide3.addShape(pptx.ShapeType.rect, { x: 9.0, y: cardY, w: cardW, h: cardH, fill: { color: COLOR_CARD }, rectRadius: 0.1 });
slide3.addText('3', { x: 9.0, y: cardY + 0.3, w: cardW, h: 0.6, fontSize: 36, bold: true, color: COLOR_ACCENT, align: 'center' });
slide3.addText('Reward Signal Sparsity', { x: 9.3, y: cardY + 1.2, w: cardW - 0.6, h: 0.5, fontSize: 20, bold: true, color: COLOR_TEXT_PRIMARY, align: 'center' });
slide3.addText('In long chain-of-thought tasks, only the final <eos> token typically receives a reward, exacerbating the difficulty of credit assignment.', { x: 9.3, y: cardY + 1.8, w: cardW - 0.6, h: 2.0, fontSize: 15, color: COLOR_TEXT_SECONDARY, align: 'center', valign: 'top' });

// Slide 4: VAPO Framework Overview
let slide4 = pptx.addSlide({ masterName: 'MASTER_SLIDE' });
addHeader(slide4, 'VAPO Framework: Integrated Solutions for Value-Model-Based Reasoning RL');

// Overview component diagram
const comps = [
  { name: 'Value-Pretraining', desc: 'Pre-trains value model before RL to reduce initial bias', icon: 'bias' },
  { name: 'Decoupled-GAE', desc: 'Separates GAE computation to handle value estimation more robustly', icon: 'calc' },
  { name: 'Length-Adaptive GAE', desc: 'Dynamically adjusts λ in GAE based on response length', icon: 'adapt' },
  { name: 'Clip-Higher', desc: 'Asymmetric clipping to encourage exploration', icon: 'clip' },
  { name: 'Token-Level Loss', desc: 'Normalizes loss at the token level rather than sequence', icon: 'loss' },
  { name: 'Positive Example LM Loss', desc: 'Self-imitation learning on correct trajectories', icon: 'pos' },
  { name: 'Group-Sampling', desc: 'Samples multiple responses per prompt for better baseline estimation', icon: 'sample' }
];

slide4.addShape(pptx.ShapeType.roundRect, { x: 0.5, y: 1.8, w: 12.3, h: 5.0, fill: { color: COLOR_CARD }, rectRadius: 0.05 });

let curX = 1.0;
let curY = 2.2;
comps.forEach((comp, idx) => {
  if (idx === 4) { curX = 7.0; curY = 2.2; }

  slide4.addShape(pptx.ShapeType.ellipse, { x: curX, y: curY, w: 0.4, h: 0.4, fill: { color: COLOR_ACCENT } });
  slide4.addText((idx+1).toString(), { x: curX, y: curY, w: 0.4, h: 0.4, align: 'center', color: COLOR_BG, bold: true, fontSize: 12 });
  slide4.addText(comp.name, { x: curX + 0.6, y: curY - 0.05, w: 4.5, h: 0.3, fontSize: 16, bold: true, color: COLOR_TEXT_PRIMARY });
  slide4.addText(comp.desc, { x: curX + 0.6, y: curY + 0.25, w: 4.8, h: 0.4, fontSize: 12, color: COLOR_TEXT_SECONDARY, valign: 'top' });

  curY += 1.1;
});

// Central mapping arrow representation
slide4.addShape(pptx.ShapeType.rightArrow, { x: 6.0, y: 3.5, w: 0.8, h: 0.5, fill: { color: COLOR_ACCENT2 } });

// Slide 5: Length-Adaptive GAE
let slide5 = pptx.addSlide({ masterName: 'MASTER_SLIDE' });
addHeader(slide5, 'Length-Adaptive GAE: Dynamic λ Adjustment for Variable Response Lengths');

slide5.addText('Novel Technique Optimizing Bias-Variance Tradeoff', { x: 0.5, y: 1.6, w: 12.3, h: 0.5, fontSize: 20, color: COLOR_TEXT_PRIMARY, italic: true });

slide5.addShape(pptx.ShapeType.rect, { x: 1.0, y: 2.5, w: 5.0, h: 3.5, fill: { color: COLOR_CARD }, rectRadius: 0.1 });
slide5.addText('Short Responses', { x: 1.0, y: 2.8, w: 5.0, h: 0.5, align: 'center', fontSize: 22, bold: true, color: COLOR_TEXT_PRIMARY });
slide5.addText('Lower λ', { x: 1.0, y: 3.5, w: 5.0, h: 0.6, align: 'center', fontSize: 28, bold: true, color: 'FF6B6B' });
slide5.addText('Prioritizes lower variance over bias.', { x: 1.2, y: 4.5, w: 4.6, h: 1.0, align: 'center', fontSize: 16, color: COLOR_TEXT_SECONDARY });

slide5.addShape(pptx.ShapeType.rect, { x: 7.3, y: 2.5, w: 5.0, h: 3.5, fill: { color: COLOR_CARD }, rectRadius: 0.1 });
slide5.addText('Long Responses', { x: 7.3, y: 2.8, w: 5.0, h: 0.5, align: 'center', fontSize: 22, bold: true, color: COLOR_TEXT_PRIMARY });
slide5.addText('Higher λ', { x: 7.3, y: 3.5, w: 5.0, h: 0.6, align: 'center', fontSize: 28, bold: true, color: COLOR_ACCENT });
slide5.addText('Prioritizes lower bias over variance, critical for long reasoning chains.', { x: 7.5, y: 4.5, w: 4.6, h: 1.0, align: 'center', fontSize: 16, color: COLOR_TEXT_SECONDARY });

// Slide 6: AIME Score Comparison
let slide6 = pptx.addSlide({ masterName: 'MASTER_SLIDE' });
addHeader(slide6, 'VAPO Scores 60.4 on AIME 2024 — 10+ Points Above DAPO');

// Chart data
let dataChart6 = [
  {
    name: 'AIME 2024 Score',
    labels: ['Vanilla PPO', 'DeepSeek-R1-Zero (Qwen-32B)', 'DAPO', 'VAPO'],
    values: [5, 47, 50, 60]
  }
];

slide6.addChart(pptx.ChartType.bar, dataChart6, {
  x: 0.5, y: 1.8, w: 6.5, h: 4.8,
  barDir: 'col',
  dataLabelColor: COLOR_TEXT_PRIMARY,
  showValue: true,
  dataLabelFontSize: 14,
  dataLabelFontBold: true,
  catAxisLabelColor: COLOR_TEXT_SECONDARY,
  valAxisLabelColor: COLOR_TEXT_SECONDARY,
  catAxisLabelFontSize: 12,
  valAxisLabelFontSize: 12,
  chartColors: [COLOR_ACCENT2, COLOR_ACCENT2, COLOR_ACCENT2, COLOR_ACCENT],
  showLegend: false,
  gridLineColor: '2A3B5C',
  valAxisMaxVal: 70
});

// Assuming figure_2.jpg is available
slide6.addImage({ path: '/app/benchmark/assets/figure_2.jpg', x: 7.5, y: 2.5, w: 5.3, h: 3.5, sizing: { type: 'contain' } });
slide6.addText('Training curve showing VAPO outperforming DAPO consistently', { x: 7.5, y: 6.1, w: 5.3, h: 0.4, fontSize: 12, color: COLOR_TEXT_SECONDARY, align: 'center' });

// Slide 7: Training Efficiency Curves
let slide7 = pptx.addSlide({ masterName: 'MASTER_SLIDE' });
addHeader(slide7, 'VAPO Reaches SOTA in 5K Steps — Half the Training Budget');

slide7.addImage({ path: '/app/benchmark/assets/figure_2.jpg', x: 0.5, y: 1.8, w: 5.8, h: 4.0, sizing: { type: 'contain' } });
slide7.addText('Training Accuracy Curve', { x: 0.5, y: 6.0, w: 5.8, h: 0.4, fontSize: 16, bold: true, color: COLOR_TEXT_PRIMARY, align: 'center' });
slide7.addText('Reaches 60% accuracy at step 4,500. DAPO plateaus near 50% at step 5,500.', { x: 0.5, y: 6.4, w: 5.8, h: 0.6, fontSize: 13, color: COLOR_TEXT_SECONDARY, align: 'center', valign: 'top' });

slide7.addImage({ path: '/app/benchmark/assets/figure_3.jpg', x: 7.0, y: 1.8, w: 5.8, h: 4.0, sizing: { type: 'contain' } });
slide7.addText('Mean Response Length', { x: 7.0, y: 6.0, w: 5.8, h: 0.4, fontSize: 16, bold: true, color: COLOR_TEXT_PRIMARY, align: 'center' });
slide7.addText('Generates longer chains (~6,000 tokens) vs DAPO (~4,500), indicating deeper reasoning.', { x: 7.0, y: 6.4, w: 5.8, h: 0.6, fontSize: 13, color: COLOR_TEXT_SECONDARY, align: 'center', valign: 'top' });

// Slide 8: Ablation Study
let slide8 = pptx.addSlide({ masterName: 'MASTER_SLIDE' });
addHeader(slide8, 'Ablation: Every Component Matters — Value-Pretraining Is Critical');

let rows = [
  [{ text: 'Model Configuration', options: { bold: true, color: COLOR_TEXT_PRIMARY, fill: COLOR_ACCENT2 } }, { text: 'AIME24 avg@32', options: { bold: true, color: COLOR_TEXT_PRIMARY, fill: COLOR_ACCENT2 } }, { text: 'Delta', options: { bold: true, color: COLOR_TEXT_PRIMARY, fill: COLOR_ACCENT2 } }],
  ['VAPO (Full)', '60', '-'],
  ['w/o Group-Sampling', '55', '-5'],
  ['w/o Positive Example LM Loss', '54', '-6'],
  ['w/o Token-level Loss', '53', '-7'],
  ['w/o Clip-Higher', '46', '-14'],
  ['w/o Length-adaptive GAE', '45', '-15'],
  ['w/o Decoupled-GAE', '33', '-27'],
  [{ text: 'w/o Value-Pretraining', options: { bold: true, color: 'FF6B6B' } }, { text: '11', options: { bold: true, color: 'FF6B6B' } }, { text: '-49', options: { bold: true, color: 'FF6B6B' } }]
];

slide8.addTable(rows, {
  x: 1.0, y: 1.8, w: 11.3,
  colW: [5.3, 3.0, 3.0],
  rowH: 0.45,
  fill: COLOR_CARD,
  color: COLOR_TEXT_PRIMARY,
  fontSize: 14,
  valign: 'middle',
  align: 'center',
  border: { type: 'solid', color: '2A3B5C', pt: 1 }
});

// Left align first column
// Note: pptxgenjs table cell formatting for align on specific cells is possible, but general layout works for now.

// Slide 9: Key Takeaways
let slide9 = pptx.addSlide({ masterName: 'MASTER_SLIDE' });
addHeader(slide9, 'Key Takeaways: Value-Model-Based RL Is Back');

slide9.addShape(pptx.ShapeType.rect, { x: 0.5, y: 1.8, w: 12.3, h: 5.0, fill: { color: COLOR_CARD }, rectRadius: 0.05 });

const takeaways = [
  { title: 'Value-Model-Based Superiority:', text: 'Can surpass value-free methods when challenges (bias, heterogeneous lengths, reward sparsity) are systematically addressed.' },
  { title: 'Crucial Value Pretraining:', text: 'The single most important component (+49 points). Without it, value-model-based RL fails on long reasoning tasks.' },
  { title: 'Length-Adaptive GAE:', text: 'A novel and critical technique addressing the heterogeneous sequence length problem unique to long-CoT reasoning.' },
  { title: 'Exceptional Stability:', text: 'VAPO exhibits no training crashes across multiple runs, achieving SOTA efficiently (~5K steps).' },
  { title: 'Future Implications:', text: 'Paves the way for scaling reasoning models beyond trajectory-level reinforcement, enabling finer-grained policy improvement.' }
];

let tkY = 2.1;
takeaways.forEach((tk) => {
  slide9.addShape(pptx.ShapeType.rect, { x: 1.0, y: tkY, w: 0.2, h: 0.2, fill: { color: COLOR_ACCENT } });
  slide9.addText(
    [
      { text: tk.title + ' ', options: { bold: true, color: COLOR_ACCENT } },
      { text: tk.text, options: { color: COLOR_TEXT_PRIMARY } }
    ],
    { x: 1.3, y: tkY - 0.1, w: 11.0, h: 0.5, fontSize: 16, valign: 'top' }
  );
  tkY += 0.9;
});

// Save
pptx.writeFile({ fileName: '/app/output/final_deck.pptx' }).then(fileName => {
  console.log(`Saved!`);
});

